const priorityLabel={high:'优先处理',normal:'普通',low:'可稍后'};
export function todayKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
export function orderedTasks(tasks){return [...tasks].sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'9999').localeCompare(b.due||'9999')||({high:0,normal:1,low:2}[a.priority]-{high:0,normal:1,low:2}[b.priority])||a.created.localeCompare(b.created));}
export function deadlineLabel(task){if(!task.due)return '未设截止日期';const today=todayKey();if(task.done)return `截止 ${task.due}`;return task.due<today?`已逾期 · ${task.due}`:task.due===today?'今天截止':`截止 ${task.due}`;}
function taskRow(t,esc){return `<article class="school-task ${t.done?'is-done':''}" id="school-task-${esc(t.id)}" tabindex="-1"><label><input type="checkbox" data-school-toggle="${esc(t.id)}" ${t.done?'checked':''}><span><strong>${esc(t.title)}</strong><small>${esc(t.course||'未分类课程')} · ${esc(deadlineLabel(t))}</small></span></label><div class="school-task-actions"><span class="priority ${t.priority}">${priorityLabel[t.priority]}</span><button data-action="school-edit" data-id="${esc(t.id)}">编辑</button><button data-action="school-delete" data-id="${esc(t.id)}">删除</button></div>${t.note?`<p class="task-note">${esc(t.note)}</p>`:''}</article>`;}
export function schoolHome(school,esc,dateText){
 const pending=orderedTasks(school.tasks).filter(t=>!t.done),done=school.tasks.filter(t=>t.done).length,total=school.tasks.length,next=pending[0],allDone=total>0&&pending.length===0,recent=school.records.slice(0,3),overdue=pending.filter(t=>t.due&&t.due<todayKey()).length;
 return `<section class="intro home-intro"><div><h1>Jarvais，先理清校内任务。</h1><p>把课程作业、考试和小组事项放在这里。所有任务与日期由你填写。</p></div><span class="motto">Never give up</span></section>
 <section class="plan-overview"><div class="plan-top"><h2>校内任务进度</h2><a href="#route">管理全部任务 ↗</a></div><div class="school-stats"><div><strong>${pending.length}</strong><span>待完成</span></div><div><strong>${done}</strong><span>已完成 / 共 ${total} 项</span></div><div><strong>${overdue}</strong><span>已逾期</span></div></div></section>
 <div class="home-content"><section><h2 class="home-section-title">今日优先处理<span>按截止日期，再按优先级排列</span></h2><div class="task-card home-task"><div class="task-top"><span class="pill">${next?esc(next.course||'校内任务'):allDone?'已填写的任务均已完成':'从你自己的任务开始'}</span><span class="task-meta">${next?esc(deadlineLabel(next)):''}</span></div><h2>${next?esc(next.title):allDone?'已添加的任务都完成了。':'先添加一项真实的任务。'}</h2><p class="description">${next?esc(next.note||'先把这项任务拆成一个可以马上执行的小动作。'):allDone?'回看已完成的任务，整理本次收获。也可以继续添加新的校内事项。':'课程报告、复习安排或小组分工，都可以放在这里。'}</p><div class="first-action"><small>第一步就做这个</small><p>${next?'查看任务要求，写下这次要完成的一个具体动作。':allDone?'写下一条校内学习感想，给下一次留下线索。':'填写任务名称、课程和你确认过的截止日期。'}</p></div><div class="task-foot"><button class="primary" data-action="${next?'school-open':allDone?'school-list':'school-add'}" ${next?`data-id="${esc(next.id)}"`:''}>${next?'查看任务详情':allDone?'查看全部任务':'添加校内任务'} ↗</button></div></div></section>
 <section class="home-notes"><h2 class="home-section-title">校内学习感想<span>与 AI、韩语分开记录</span></h2><div class="notes-box"><div class="notes-summary"><span>${school.records.length} 篇感想</span><a href="#records">查看全部 ↗</a></div>${recent.length?recent.map(r=>`<button class="home-note" data-action="school-open-note" data-id="${esc(r.id)}"><time>${esc(dateText(r.date))}</time><p>${esc(r.text.slice(0,100))}</p></button>`).join(''):'<div class="home-notes-empty"><span class="empty-symbol">✎</span><h3>留住课堂与项目的收获</h3><p>记下学到什么、哪里卡住，以及下次从哪里继续。</p></div>'}<button class="secondary" data-action="records">写校内学习感想 ↗</button></div></section></div>`;
}
export function schoolRoute(school,esc){
 return `<div class="page-intro school-page-heading"><div><span class="eyebrow">JARVAIS WANG · UNIVERSITY</span><h1>我的校内任务</h1><p>课程、截止日期与具体要求，以你实际填写的信息为准。</p></div><button class="primary" data-action="school-add">＋ 添加任务</button></div>${school.tasks.length?orderedTasks(school.tasks).map(t=>taskRow(t,esc)).join(''):'<div class="empty-state"><div class="empty-symbol">＋</div><h3>还没有添加校内任务</h3><p>从最近的一份作业开始，写下名称、所属课程和截止日期。</p></div>'}`;
}
export function schoolForm(task,esc){
 const t=task??{id:'',title:'',course:'',due:'',priority:'normal',note:''};
 return `<span class="eyebrow">UNIVERSITY TASK</span><h2 id="dialog-title">${task?'编辑':'添加'}校内任务</h2><form id="school-task-form" data-edit-id="${esc(t.id)}"><div class="field"><label for="school-title">任务名称</label><input id="school-title" name="title" maxlength="200" required value="${esc(t.title)}" placeholder="填写你真实要完成的作业或事项"></div><div class="field"><label for="school-course">所属课程（选填）</label><input id="school-course" name="course" maxlength="200" value="${esc(t.course)}"></div><div class="school-form-row"><div class="field"><label for="school-due">截止日期（选填）</label><input id="school-due" type="date" name="due" value="${esc(t.due)}"></div><div class="field"><label for="school-priority">优先级</label><select id="school-priority" name="priority">${Object.entries(priorityLabel).map(([v,label])=>`<option value="${v}" ${t.priority===v?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="field"><label for="school-note">任务要求 / 下一步（选填）</label><textarea id="school-note" name="note" maxlength="10000">${esc(t.note)}</textarea></div><p id="school-error" role="alert"></p><button type="submit" class="primary">保存任务 ↗</button></form>`;
}
export function schoolJournal(school,esc,dateText){
 return `<div class="page-intro"><span class="eyebrow">JARVAIS WANG · UNIVERSITY JOURNAL</span><h1>校内学习感想</h1><p>课堂理解、作业卡点、项目复盘，都记在这个板块里。</p></div><div class="record-layout"><section class="lesson-panel"><h2 id="school-journal-heading">写一条校内学习感想</h2><form id="school-journal-form" data-edit-id=""><div class="field"><label for="school-record-task">关联任务（选填）</label><select id="school-record-task" name="taskId"><option value="">不关联具体任务</option>${school.tasks.map(t=>`<option value="${esc(t.id)}">${esc(t.title)}</option>`).join('')}</select></div><div class="field"><label for="school-record-text">今天的理解 / 学习感想</label><textarea id="school-record-text" name="text" maxlength="10000" required></textarea></div><div class="field"><label for="school-record-blocker">下次从这里继续（选填）</label><textarea id="school-record-blocker" name="blocker" maxlength="10000"></textarea></div><button type="submit" class="primary">保存校内学习感想 ↗</button></form></section><section><div class="section-heading" style="margin-top:0"><h2>过去的校内学习感想</h2><span>${school.records.length} 篇</span></div>${school.records.length?school.records.map(r=>`<article class="record-item" id="school-record-${esc(r.id)}" tabindex="-1"><time>${esc(dateText(r.date))}</time><h3>${esc(school.tasks.find(t=>t.id===r.taskId)?.title||'校内学习')}</h3><p>${esc(r.text)}</p>${r.blocker?`<p class="record-blocker">下次继续：${esc(r.blocker)}</p>`:''}<div class="record-actions"><button data-action="school-edit-note" data-id="${esc(r.id)}">编辑</button><button data-action="school-delete-note" data-id="${esc(r.id)}">删除</button></div></article>`).join(''):'<div class="empty-state"><h3>从一句话开始记录</h3><p>今天弄懂了什么？下次要解决什么？</p></div>'}</section></div>`;
}
